create schema colega;
create table colega.usuarios   (id serial, alias varchar(20) unique, creado text);
create table colega.respuestas (usuario int, pregunta int, elegida int, puntos numeric);
create table colega.miembros   (grupo int, usuario int, rol text);
create table colega.partidas   (id serial primary key, jugador1 int, jugador2 int, estado text);

-- Mini Senda: esquema de referencia (PostgreSQL 16)
create table usuarios (
  id     uuid primary key default gen_random_uuid(),
  alias  text not null check (char_length(alias) between 3 and 20),
  creado timestamptz not null default now()
);
create unique index usuarios_alias_unico on usuarios (lower(alias));

create table libros (
  codigo text primary key check (codigo ~ '^[a-z0-9]{3,10}$'),
  nombre text not null unique
);
create table capitulos (
  libro  text     not null references libros,
  numero smallint not null check (numero > 0),
  primary key (libro, numero)
);
create table lecturas (
  usuario  uuid     not null references usuarios on delete cascade,
  libro    text     not null,
  capitulo smallint not null,
  leido_en timestamptz not null default now(),
  primary key (usuario, libro, capitulo),
  foreign key (libro, capitulo) references capitulos
);

create table preguntas (
  id         bigint generated always as identity primary key,
  enunciado  text     not null check (char_length(enunciado) >= 10),
  opciones   text[]   not null check (cardinality(opciones) = 4 and array_position(opciones, null) is null),
  correcta   smallint not null check (correcta between 1 and 4),
  dificultad smallint not null check (dificultad between 1 and 3),
  estado     text     not null default 'borrador' check (estado in ('borrador','publicada','retirada')),
  libro      text     not null,
  capitulo   smallint not null,
  versiculo  smallint not null check (versiculo > 0),
  foreign key (libro, capitulo) references capitulos
);

create table partidas (
  id     bigint generated always as identity primary key,
  estado text not null default 'en_curso' check (estado in ('en_curso','terminada','vencida')),
  creada timestamptz not null default now()
);
create table partida_jugadores (
  partida bigint   not null references partidas on delete cascade,
  usuario uuid     not null references usuarios on delete cascade,
  orden   smallint not null check (orden in (1, 2)),
  primary key (partida, usuario),
  unique (partida, orden)
);
create table partida_preguntas (
  partida  bigint   not null references partidas on delete cascade,
  orden    smallint not null check (orden between 1 and 5),
  pregunta bigint   not null references preguntas,
  primary key (partida, orden),
  unique (partida, pregunta)
);
create table jugadas (
  partida    bigint   not null,
  usuario    uuid     not null,
  pregunta   bigint   not null,
  elegida    smallint not null check (elegida between 1 and 4),
  ms         int      not null check (ms >= 0),
  respondida timestamptz not null default now(),
  primary key (partida, usuario, pregunta),
  foreign key (partida, usuario)  references partida_jugadores,
  foreign key (partida, pregunta) references partida_preguntas (partida, pregunta)
);

create table grupos (
  id     bigint generated always as identity primary key,
  nombre text not null check (char_length(nombre) between 3 and 40),
  creado timestamptz not null default now()
);
create table miembros (
  grupo   bigint not null references grupos on delete cascade,
  usuario uuid   not null references usuarios on delete cascade,
  rol     text   not null default 'miembro' check (rol in ('lider','ayudante','miembro')),
  desde   timestamptz not null default now(),
  primary key (grupo, usuario)
);
create unique index un_solo_lider on miembros (grupo) where rol = 'lider';

create table copas (
  id      text primary key,
  empieza date not null,
  termina date not null,
  check (termina > empieza)
);
create table copa_resultados (
  copa     text     not null references copas,
  usuario  uuid     not null references usuarios on delete cascade,
  puntos   int      not null check (puntos between 0 and 10000),
  aciertos smallint not null check (aciertos between 0 and 10),
  ms       int      not null check (ms >= 0),
  primary key (copa, usuario)
);
